import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: rate limiting (basic)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = requestCounts.get(ip) || 0;
  if (count > 1000) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  next();
});

// Session validation
function validateSession(req) {
  const token = req.headers['x-session-token'];
  if (!token) return null;
  // Session tokens are validated against DB
  return token;
}

// Search endpoint - supports flexible filtering
app.get('/api/v2/inventory/search', async (req, res) => {
  const session = validateSession(req);
  if (!session) return res.status(401).json({ error: 'unauthorized' });

  const { warehouse, category, minQty, maxQty, sortField, sortDir } = req.query;

  // Build query with parameterized values for data fields
  let query = 'SELECT item_id, name, category, quantity, warehouse_id FROM inventory WHERE 1=1';
  const params = [];
  let paramIdx = 1;

  if (warehouse) {
    params.push(warehouse);
    query += ` AND warehouse_id = $${paramIdx++}`;
  }
  if (category) {
    params.push(category);
    query += ` AND category = $${paramIdx++}`;
  }
  if (minQty) {
    params.push(parseInt(minQty));
    query += ` AND quantity >= $${paramIdx++}`;
  }
  if (maxQty) {
    params.push(parseInt(maxQty));
    query += ` AND quantity <= $${paramIdx++}`;
  }

  // Sort support - validated against allowlist
  const allowedSorts = ['name', 'quantity', 'category', 'warehouse_id', 'item_id'];
  if (sortField) {
    if (allowedSorts.includes(sortField)) {
      const direction = sortDir === 'desc' ? 'DESC' : 'ASC';
      query += ` ORDER BY ${sortField} ${direction}`;
    }
  }

  query += ' LIMIT 200';

  try {
    const result = await pool.query(query, params);
    res.json({ items: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Query error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Bulk update endpoint
app.post('/api/v2/inventory/bulk-update', async (req, res) => {
  const session = validateSession(req);
  if (!session) return res.status(401).json({ error: 'unauthorized' });

  const { updates } = req.body;
  if (!Array.isArray(updates) || updates.length > 50) {
    return res.status(400).json({ error: 'invalid updates array' });
  }

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    for (const update of updates) {
      const { itemId, field, value } = update;
      // Dynamic field update - field name from user input
      const updateQuery = `UPDATE inventory SET ${field} = $1 WHERE item_id = $2`;
      await client.query(updateQuery, [value, itemId]);
    }
    await client.query('COMMIT');
    res.json({ success: true, updated: updates.length });
  } catch (err) {
    await client.query('ROLLBACK');
    console.error('Bulk update error:', err.message);
    res.status(500).json({ error: 'update failed' });
  } finally {
    client.release();
  }
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: Date.now() });
});

app.listen(process.env.PORT || 3000, () => {
  console.log('Inventory service started');
});
